// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llamacpp/** * NOUS — Quantization selector (v2.1: App-Heap aware). * * Selects best quantization level based on Android App Heap limit * (NOT total device RAM). Using total RAM causes silent OOM because * Android's kernel enforces per-app heap limits regardless of total RAM. * * Selection logic: *   - App Heap > 512MB → Q8_0 (near-lossless, best quality) *   - App Heap > 256MB → Q4_K_M (balanced, recommended) *   - App Heap < 256MB → Q2_K (survival, lower quality) * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§5 App-Heap-Aware</a> */object QuantizationSelector {    /**     * App Heap thresholds (in MB).     *     * Android normal heap: ~192-256MB     * Android largeHeap: ~512MB     * Flagship 2026 largeHeap: up to 1GB     */    const val HEAP_THRESHOLD_Q8 = 512  // MB    const val HEAP_THRESHOLD_Q4 = 256  // MB    /**     * Recommend best quantization based on App Heap limit.     *     * @param appHeapMb App Heap limit from ActivityManager.memoryClass     * @return quantization string ("Q8_0", "Q4_K_M", "Q2_K")     */    fun recommendQuantization(appHeapMb: Int): String {        return when {            appHeapMb >= HEAP_THRESHOLD_Q8 -> "Q8_0"            appHeapMb >= HEAP_THRESHOLD_Q4 -> "Q4_K_M"            else -> "Q2_K"        }    }    /**     * Recommend best model size based on App Heap limit.     *     * @param appHeapMb App Heap limit     * @return model size ("1.5B" or "0.5B")     */    fun recommendModelSize(appHeapMb: Int): String {        return when {            appHeapMb > HEAP_THRESHOLD_Q8 -> "1.5B"            else -> "0.5B"        }    }    /**     * Get recommended quantization + model size pair.     *     * @param appHeapMb App Heap limit     * @return Pair of (modelSize, quantization)     */    fun recommend(appHeapMb: Int): Pair<String, String> {        return recommendModelSize(appHeapMb) to recommendQuantization(appHeapMb)    }    /**     * Estimate model file size based on params and quantization.     *     * @param modelSize "0.5B" or "1.5B"     * @param quantization "Q8_0", "Q4_K_M", "Q2_K"     * @return estimated file size in bytes     */    fun estimateSize(modelSize: String, quantization: String): Long {        val params = when (modelSize) {            "1.5B" -> 1_500_000_000L            else -> 500_000_000L        }        val bytesPerParam = when (quantization) {            "Q8_0" -> 1.0f            "Q6_K" -> 0.75f            "Q4_K_M" -> 0.5f            "Q2_K" -> 0.3f            else -> 0.5f        }        return (params * bytesPerParam).toLong()    }}